"use client";

import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import { useState } from "react";
import { authClient } from "@/lib/auth-client";

// Only allow same-origin relative paths to avoid open redirects.
function safeNext(next: string | null): string {
  return next && next.startsWith("/") && !next.startsWith("//") ? next : "/dashboard";
}

export function AuthForm({ mode }: { mode: "sign-in" | "sign-up" }) {
  const router = useRouter();
  const next = safeNext(useSearchParams().get("next"));
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);
  const isSignUp = mode === "sign-up";

  async function onSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError(null);
    setPending(true);
    const form = new FormData(e.currentTarget);
    const email = String(form.get("email"));
    const password = String(form.get("password"));

    const { error } = isSignUp
      ? await authClient.signUp.email({ email, password, name: String(form.get("name")) })
      : await authClient.signIn.email({ email, password });

    setPending(false);
    if (error) {
      setError(error.message ?? "Something went wrong");
      return;
    }
    router.push(next);
    router.refresh();
  }

  async function onGoogle() {
    setError(null);
    const { error } = await authClient.signIn.social({
      provider: "google",
      callbackURL: next,
      errorCallbackURL: "/sign-in",
    });
    if (error) setError(error.message ?? "Google sign-in failed");
  }

  const input = "w-full rounded border border-black/15 bg-transparent px-3 py-2 text-sm dark:border-white/20";

  return (
    <main className="mx-auto w-full max-w-sm p-8">
      <h1 className="text-2xl font-semibold">{isSignUp ? "Create your account" : "Sign in to Notely"}</h1>

      <form onSubmit={onSubmit} className="mt-6 space-y-3">
        {isSignUp && (
          <input name="name" placeholder="Name" required autoComplete="name" className={input} />
        )}
        <input name="email" type="email" placeholder="Email" required autoComplete="email" className={input} />
        <input
          name="password"
          type="password"
          placeholder="Password"
          required
          minLength={8}
          autoComplete={isSignUp ? "new-password" : "current-password"}
          className={input}
        />
        {error && <p className="text-sm text-red-600">{error}</p>}
        <button
          type="submit"
          disabled={pending}
          className="w-full rounded bg-foreground px-3 py-2 text-sm font-medium text-background disabled:opacity-50"
        >
          {pending ? "…" : isSignUp ? "Sign up" : "Sign in"}
        </button>
      </form>

      <button
        type="button"
        onClick={onGoogle}
        className="mt-3 w-full rounded border border-black/15 px-3 py-2 text-sm font-medium dark:border-white/20"
      >
        Continue with Google
      </button>

      <p className="mt-6 text-sm opacity-70">
        {isSignUp ? "Already have an account? " : "No account yet? "}
        <Link
          href={`${isSignUp ? "/sign-in" : "/sign-up"}?next=${encodeURIComponent(next)}`}
          className="underline"
        >
          {isSignUp ? "Sign in" : "Sign up"}
        </Link>
      </p>
    </main>
  );
}
